import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, AmbientLight, DirectionalLight } from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: CGroup, Mesh: CMesh, PlaneGeometry: CPlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, AmbientLight, DirectionalLight } = ctx.THREE;

  const root = new CGroup();

  // ---------- Backdrop ----------
  const backdropGeom = new CPlaneGeometry(7, 5.5);
  const gradientNode = mix(
    color(config.colors?.gradientStops?.[0]?.hex ?? '#0b0b10'),
    color(config.colors?.gradientStops?.[1]?.hex ?? '#13131a'),
    uv().y
  );
  const backdropMat = new MeshBasicNodeMaterial({ color: gradientNode });
  const backdropMesh = new CMesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -1.5);
  root.add(backdropMesh);

  // ---------- Hero Text ----------
  const heroGroup = new CGroup();
  const heroString = (config.textContent?.find(t => t.role === 'hero')?.text) ?? 'TIME, MACHINED.';
  const heroWords = heroString.split(' ');
  const heroZOffsets = [0.12, 0, -0.12];
  let cursorX = 0;
  heroWords.forEach((word, i) => {
    const txt = ctx.fontAtlas.createText(word, {
      fontSize: config.typography?.hero?.fontSize ?? 124,
      color: config.colors?.ink ?? '#16161d',
      align: 'left',
      letterSpacing: config.typography?.hero?.letterSpacing ?? -0.01,
    });
    txt.position.set(cursorX, 0.4, heroZOffsets[i] ?? 0);
    heroGroup.add(txt);
    // rough advance; actual width unknown, use a fixed step
    cursorX += 1.2;
  });
  // Center horizontally
  heroGroup.position.x = -cursorX / 2 + 0.6;
  root.add(heroGroup);

  // ---------- Subhead ----------
  const subheadString = (config.textContent?.find(t => t.role === 'subhead')?.text) ?? 'Every calibre begins as a solid billet.';
  const subhead = ctx.fontAtlas.createText(subheadString, {
    fontSize: config.typography?.subhead?.fontSize ?? 40,
    color: config.colors?.ink ?? '#16161d',
    align: 'center',
    letterSpacing: config.typography?.subhead?.letterSpacing ?? 0.02,
  });
  subhead.position.set(0, -0.65, 0);
  // Ensure opacity handling
  subhead.traverse(node => {
    if (node.material && ('transparent' in node.material)) {
      node.material.transparent = true;
      node.material.opacity = 0;
    }
  });
  root.add(subhead);

  // ---------- Caption ----------
  const captionString = (config.textContent?.find(t => t.role === 'caption')?.text) ?? 'NOVA ATELIER / CALIBRE PROGRAM';
  const caption = ctx.fontAtlas.createText(captionString, {
    fontSize: config.typography?.caption?.fontSize ?? 18,
    color: config.colors?.paper ?? '#e8ecf2',
    align: 'center',
    letterSpacing: config.typography?.caption?.letterSpacing ?? 0.12,
  });
  caption.position.set(0, 1.15, 0);
  caption.traverse(node => {
    if (node.material && ('transparent' in node.material)) {
      node.material.transparent = true;
      node.material.opacity = 0;
    }
  });
  root.add(caption);

  // ---------- Accent Underline ----------
  const underlineGeom = new CPlaneGeometry(2.6, 0.045);
  const underlineMat = new MeshStandardNodeMaterial({
    color: color(config.colors?.accent ?? '#ff2a38'),
    emissive: color(config.colors?.accent ?? '#ff2a38'),
    emissiveIntensity: 1.2,
    metalness: 0,
    roughness: 1,
  });
  const underline = new CMesh(underlineGeom, underlineMat);
  // Anchor left edge
  underline.position.set(-1.3, -0.05, 0);
  underline.scale.set(0, 1, 1);
  root.add(underline);

  // ---------- Lighting ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  root.add(keyLight);

  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-2, -2, -2);
  root.add(rimLight);

  // ---------- Cinematic Primitives ----------
  const primitiveCleanups = [];
  (config.cinematicPrimitives ?? []).forEach(p => {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const result = fn(root, p.params);
      if (result && typeof result.cleanup === 'function') {
        primitiveCleanups.push(result.cleanup);
      }
    }
  });

  // ---------- GSAP Animations ----------
  const timelines = [];

  // Underline reveal (starts after expected glyph land, approximated with delay)
  const underlineTl = gsap.timeline();
  underlineTl.to(underline.scale, {
    x: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    delay: 1.5, // rough offset after kinetic text
  });
  timelines.push(underlineTl);

  // Subhead fade‑up & rise
  const subheadTl = gsap.timeline();
  subheadTl.fromTo(
    subhead.position,
    { y: -0.65 + 0.2 },
    { y: -0.65, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  subheadTl.fromTo(
    subhead,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    '<'
  );
  timelines.push(subheadTl);

  // Caption fade‑in
  const captionTl = gsap.fromTo(
    caption,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, delay: 2, ease: 'power2.out' }
  );
  timelines.push(captionTl);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometries & materials we created
    backdropGeom.dispose();
    backdropMat.dispose();
    underlineGeom.dispose();
    underlineMat.dispose();

    // Kill GSAP timelines
    timelines.forEach(t => t.kill());

    // Primitive cleanups
    primitiveCleanups.forEach(fn => {
      try { fn(); } catch (_) {}
    });
  };

  // Placeholder for interaction handlers
  root.userData.handlers = {};

  return root;
}
